/* From Uiverse.io by ahmed150up - Tags: checkbox, lock */
.__UIV_SCOPE__ .lock-checkbox {
  position: relative;
  display: inline-block;
  width: 40px;
  height: 40px;
  margin-right: 10px;
}

.__UIV_SCOPE__ .lock-checkbox input[type="checkbox"] {
  opacity: 0;
  width: 0;
  height: 0;
}

.__UIV_SCOPE__ .lock-icon {
  fill: #00ff40;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 34px;
  height: 34px;
  transition: all 0.3s;
  cursor: pointer;
}

.__UIV_SCOPE__ .lock-checkbox input[type="checkbox"]:checked + .lock-icon {
  fill: #ff0000;
}
